"""A small deployment CLI built on click, plus helpers to drive it in-process."""
import click
from click.testing import CliRunner

ENVS = ["staging", "production", "preview"]


def complete_env(ctx, args, incomplete):
    return [e for e in ENVS if e.startswith(incomplete)]


def table_width():
    cols, _rows = click.get_terminal_size()
    return max(40, min(cols, 100))


def format_row(name, state):
    width = table_width()
    return name.ljust(width - 12) + state.rjust(12)


class PluginGroup(click.MultiCommand):
    """Commands that are looked up by name instead of being registered up front."""

    def list_commands(self, ctx):
        return ["hello"]

    def get_command(self, ctx, name):
        if name != "hello":
            return None

        @click.command()
        @click.argument("who", default="world")
        def hello(who):
            click.echo("hello {}".format(who))

        return hello


@click.group()
@click.version_option("1.2.0", prog_name="deployctl")
def cli():
    """Deploy things."""


@cli.command()
@click.argument("env", autocompletion=complete_env)
@click.option("--tag", multiple=True)
@click.option(
    "--level",
    type=click.Choice(["info", "debug"], case_sensitive=False),
    default="info",
)
@click.option("--dry-run/--no-dry-run", default=True)
def deploy(env, tag, level, dry_run):
    """Deploy to ENV."""
    verb = "would deploy" if dry_run else "deploying"
    click.echo("{} to {} [{}] tags={}".format(verb, env, level.lower(), ",".join(tag)))


@cli.command()
def status():
    """Show a status table."""
    click.echo(format_row("web", "ok"))
    click.echo(format_row("worker", "degraded"))


cli.add_command(PluginGroup(name="plugins"))


def invoke(args, **kwargs):
    """Run the CLI in-process and hand back the click Result."""
    return CliRunner().invoke(cli, args, **kwargs)


def smoke():
    """Run a couple of commands and return all their Results."""
    return [invoke(["status"]), invoke(["deploy", "staging", "--tag", "a"])]

